// ════════════════════════════════════════════════════════════════════════════
// SQUAD STORE — one roster, two places it can live.
//
//   LIVE SITE  · players in Supabase `la_players` (the canonical roster, as
//                before); the public files are regenerated by la-publish-players.
//   PREVIEW    · a copy of the deployed data/players.json held in a Netlify
//                Blob for THAT preview only, so testing never touches the
//                live roster, the live database or main.
//
// The review queue, staff confirmations and "remind me later" live in a Blob in
// both cases (no database migration needed for them). Every Blob write is
// conditional on the version that was read, so two committee members acting
// at once cannot silently overwrite each other — the loser retries on fresh
// data and an already-resolved item is reported, not re-applied.
// ════════════════════════════════════════════════════════════════════════════
'use strict';

const SCOPE = require('../deploy-scope');

let BACKEND = null;          // tests inject an in-memory store
function setBackend(b) { BACKEND = b; }

async function blobStore(event, name) {
  if (BACKEND) return BACKEND(name);
  const B = require('@netlify/blobs');
  if (event && event.blobs && B.connectLambda) B.connectLambda(event);
  return B.getStore({ name, consistency: 'strong' });
}

function storeName(scope, what) {
  return 'squad-' + what + (scope.production ? '' : '--' + scope.key);
}

/** Read-modify-write with optimistic concurrency. fn(doc) returns the new doc. */
async function update(store, key, empty, fn) {
  for (let attempt = 0; attempt < 5; attempt++) {
    const cur = await store.getWithMetadata(key, { type: 'json' });
    const doc = cur && cur.data ? cur.data : JSON.parse(JSON.stringify(empty));
    const next = await fn(doc);
    if (next === undefined) return { doc, changed: false };
    const opts = cur && cur.etag ? { onlyIfMatch: cur.etag } : { onlyIfNew: true };
    const w = await store.setJSON(key, next, opts);
    if (w && w.modified) return { doc: next, changed: true };
  }
  const e = new Error('busy'); e.code = 'busy'; throw e;
}

/* ── the review queue ───────────────────────────────────────────────────── */
const EMPTY_REVIEW = { proposals: [], reviews: [], remind: {}, sources: {}, aliases: {} };

async function review(event) {
  const scope = SCOPE.scopeOf(event);
  const s = await blobStore(event, storeName(scope, 'review'));
  return {
    scope,
    read: async () => { const r = await s.get('review.json', { type: 'json' }); return r || JSON.parse(JSON.stringify(EMPTY_REVIEW)); },
    update: (fn) => update(s, 'review.json', EMPTY_REVIEW, fn),
  };
}

/* ── the roster ─────────────────────────────────────────────────────────── */
const STATUSES = ['active', 'on_loan', 'left', 'needs_review', 'injured', 'released', 'pending'];
const CURRENT = ['active', 'injured', 'on_loan'];   // shown in the current squad

function slug(n) { return 'player-' + String(n || '').toLowerCase().replace(/\s+/g, '-'); }

/** Preview roster: seeded once from the files this preview deploy serves. */
async function previewRoster(event, scope) {
  const s = await blobStore(event, storeName(scope, 'roster'));
  async function seed() {
    let players = [];
    try {
      const r = await fetch('https://' + scope.host + '/data/players.json', { signal: AbortSignal.timeout(8000) });
      if (r.ok) players = ((await r.json()).players || []);
    } catch (e) { /* an empty seed is honest: the preview shows no players */ }
    return { seededFrom: 'data/players.json on ' + scope.host, seededAt: new Date().toISOString(), version: 0,
      players: players.map((p, i) => ({ id: 'pv-' + (i + 1), slug: p.id || slug(p.name), name: p.name, position: p.position || '',
        squad_no: p.number || null, photo_url: p.photo || '', status: 'active', age: p.age || null, photo_consent: null,
        role: p.role || '', bio: p.bio || '', nationality: p.nationality || '', nickname: p.nickname || '',
        apps: p.apps || 0, goals: p.goals || 0, assists: p.assists || 0 })) };
  }
  async function doc() { return (await s.get('roster.json', { type: 'json' })) || seed(); }
  return {
    production: false,
    list: async () => (await doc()).players,
    meta: async () => { const d = await doc(); return { version: d.version || 0, updatedAt: d.updatedAt || d.seededAt }; },
    mutate: async (fn) => {
      const seeded = await doc();
      return update(s, 'roster.json', seeded, async (d) => {
        const out = await fn(d.players);
        if (out === undefined) return undefined;
        d.version = (d.version || 0) + 1; d.updatedAt = new Date().toISOString();
        return d;
      });
    },
  };
}

/** Live roster: la_players, exactly as la-roster uses it. */
function liveRoster() {
  const L = require('../lane');
  return {
    production: true,
    list: async () => (await L.sel('la_players?select=id,name,position,squad_no,photo_url,status,age,photo_consent&order=squad_no.asc,name.asc')) || [],
    insert: (row) => L.ins('la_players', row),
    patch: (id, patch) => L.upd('la_players', 'id=eq.' + encodeURIComponent(id), patch),
  };
}

async function roster(event) {
  const scope = SCOPE.scopeOf(event);
  return scope.production ? liveRoster() : previewRoster(event, scope);
}

module.exports = { setBackend, blobStore, storeName, update, review, roster, STATUSES, CURRENT, slug, EMPTY_REVIEW };
